"""Splitting money between parties."""

from collections.abc import Sequence


def _plain_split(total: int, weights: Sequence[int], indices: list[int]) -> dict[int, int]:
    weight_sum = sum(weights[i] for i in indices)
    shares = {i: total * weights[i] // weight_sum for i in indices}
    leftover = total - sum(shares.values())
    by_remainder = sorted(indices, key=lambda i: (-(total * weights[i] % weight_sum), i))
    for i in by_remainder[:leftover]:
        shares[i] += 1
    return shares


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if len(weights) == 0:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if sum(weights) == 0:
        raise ValueError("weights must not add up to zero")
    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(c < 0 for c in caps):
            raise ValueError("caps must not be negative")

    result = [0] * len(weights)
    active = [i for i, w in enumerate(weights) if w > 0]

    if caps is None:
        result_map = _plain_split(total, weights, active)
        for i, share in result_map.items():
            result[i] = share
        return result

    if sum(caps[i] for i in active) < total:
        raise ValueError("caps of the weighted parties cannot hold total")

    remaining = total
    while active:
        shares = _plain_split(remaining, weights, active)
        over = [i for i in active if shares[i] > caps[i]]
        if not over:
            for i, share in shares.items():
                result[i] = share
            break
        for i in over:
            result[i] = caps[i]
            remaining -= caps[i]
        active = [i for i in active if i not in over]
    return result
